import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    n = int(data[0].strip())
    inventory = {}

    for i in range(1, n + 1):
        if i >= len(data):
            break
        line = data[i].strip()
        if not line:
            continue

        parts = line.split()
        if not parts:
            continue

        op = parts[0]

        if op == "ADD":
            product_id = int(parts[1])
            name = parts[2]
            if name.startswith('"') and name.endswith('"'):
                name = name[1:-1]
            quantity = int(parts[3])
            price = float(parts[4])
            inventory[product_id] = {
                'id': product_id,
                'name': name,
                'quantity': quantity,
                'price': price
            }

        elif op == "UPDATE":
            product_id = int(parts[1])
            new_quantity = int(parts[2])
            if product_id in inventory:
                inventory[product_id]['quantity'] = new_quantity
                print("Product updated successfully")
            else:
                print("Product not found")

        elif op == "REMOVE":
            product_id = int(parts[1])
            if product_id in inventory:
                del inventory[product_id]
                print("Product removed successfully")
            else:
                print("Product not found")

        elif op == "TOTAL":
            total = sum(p['quantity'] * p['price'] for p in inventory.values())
            print(f"{total:.2f}")

        elif op == "LIST":
            for pid in sorted(inventory.keys()):
                p = inventory[pid]
                print(f'{p["id"]} "{p["name"]}" {p["quantity"]} {p["price"]}')

if __name__ == "__main__":
    main()
